function markdownToHtml(md) {
  return md
    .replace(/^# (.+)$/gm, '<h1>$1</h1>')
    .replace(/^## (.+)$/gm, '<h2>$1</h2>')
    .replace(/- \[ \] (.+)/g, '<li class="todo">$1</li>')
    .replace(/- \[x\] (.+)/g, '<li class="done">$1</li>');
}

